export async function summarise(article: string): Promise<string> {
  const res = await client.chat.completions.create({
    model: "gpt-4o-mini",
    messages: [{ role: "user", content: `Summarise this article in three sentences:\n\n${article}` }],
  })
  return res.choices[0]?.message.content ?? ""
}
